Q: Angular CDK : attach overlay to a clicked element A: <p>I found an easier way with Claude:</p>
<pre class="lang-html prettyprint-override"><code>&lt;ng-template #popoverTpl
    cdkConnectedOverlay
    [cdkConnectedOverlayOrigin]=&quot;activeOrigin()!&quot;
    [cdkConnectedOverlayOpen]=&quot;activeOrigin() !== null&quot;
    [cdkConnectedOverlayPositions]=&quot;positions&quot;
    [cdkConnectedOverlayPush]=&quot;true&quot;
    [cdkConnectedOverlayViewportMargin]=&quot;8&quot;
    [cdkConnectedOverlayScrollStrategy]=&quot;repositionScrollStrategy&quot;
    (backdropClick)=&quot;activeOrigin.set(null)&quot;
    (detach)=&quot;activeOrigin.set(null)&quot;
    [cdkConnectedOverlayHasBackdrop]=&quot;true&quot;
    cdkConnectedOverlayBackdropClass=&quot;cdk-overlay-transparent-backdrop&quot;
    &gt;
  @if (activeElement(); as ch){
  &lt;div class=&quot;popover-card&quot;&gt;
    Hello from popover!
  &lt;/div&gt;
  }
&lt;/ng-template&gt;
</code></pre>
<p>On your clickable element:</p>
<pre class="lang-html prettyprint-override"><code>&lt;div 
  cdkOverlayOrigin #origin=&quot;cdkOverlayOrigin&quot;
  (click)=&quot;showPopover(origin, value)&quot;
  &gt;...&lt;/div&gt;
</code></pre>
<p>And code:</p>
<pre class="lang-js prettyprint-override"><code>#overlay = inject(Overlay);
activeOrigin = signal&lt;CdkOverlayOrigin | null&gt;(null);
activeElement = signal&lt;any | null&gt;(null);

positions: ConnectedPosition[] = [
  { originX: 'start', originY: 'center', overlayX: 'end',   overlayY: 'center', offsetX: -8 },
  { originX: 'end',   originY: 'center', overlayX: 'start', overlayY: 'center', offsetX:  8 },
];
repositionScrollStrategy: ScrollStrategy = this.#overlay.scrollStrategies.reposition();

showPopover(origin: CdkOverlayOrigin, element: any) {
  // isSame: reset when clicking the same target again
  const isSame = this.activeOrigin() === origin;

  // Set
  this.activeOrigin.set(isSame ? null : origin);
  this.activeChamber.set(isSame ? null : chamber);
}

</code></pre>
